const input = $input.first().json;
const entryIn = input.entry || {};
const employee = input.employee || {};
const assignment = input.assignment || {};
const settings = input.settings || {};
const existingDayRows = Array.isArray(input.existing_day_rows) ? input.existing_day_rows : [];
const todayLocal = input.today_local;

const errors = [];
const warnings = [];
const missingFields = [];

const LOW_CONF = settings.LOW_CONFIDENCE_THRESHOLD != null ? Number(settings.LOW_CONFIDENCE_THRESHOLD) : 0.75;
const HOURS_STEP = settings.HOURS_STEP != null ? Number(settings.HOURS_STEP) : 0.25;
const MAX_HOURS_PER_ENTRY = settings.MAX_HOURS_PER_ENTRY != null ? Number(settings.MAX_HOURS_PER_ENTRY) : 12;
const MAX_HOURS_PER_DAY_DEFAULT = settings.MAX_HOURS_PER_DAY != null ? Number(settings.MAX_HOURS_PER_DAY) : 16;
const BACKDATE_DAYS = settings.BACKDATE_DAYS != null ? Number(settings.BACKDATE_DAYS) : 7;
const WORKING_DAYS = Array.isArray(settings.WORKING_DAYS) ? settings.WORKING_DAYS : [1, 2, 3, 4, 5];
const TASK_MIN_CHARS = settings.TASK_MIN_CHARS != null ? Number(settings.TASK_MIN_CHARS) : 10;
const TASK_MAX_CHARS = settings.TASK_MAX_CHARS != null ? Number(settings.TASK_MAX_CHARS) : 500;
const COMMENT_MAX_CHARS = settings.COMMENT_MAX_CHARS != null ? Number(settings.COMMENT_MAX_CHARS) : 500;
const DUPLICATE_POLICY = (settings.DUPLICATE_POLICY || 'WARN').toString().toUpperCase();

function normaliseForMatch(str) {
  return (str || '').toString().toLowerCase().replace(/[^a-z0-9]/g, '');
}

function bigrams(str) {
  const s = str;
  const out = [];
  for (let i = 0; i < s.length - 1; i++) out.push(s.slice(i, i + 2));
  return out;
}

function diceCoefficient(a, b) {
  const na = normaliseForMatch(a);
  const nb = normaliseForMatch(b);
  if (!na.length || !nb.length) return 0;
  if (na === nb) return 1;
  const bgA = bigrams(na);
  const bgB = bigrams(nb);
  if (!bgA.length || !bgB.length) return na === nb ? 1 : 0;
  const counts = new Map();
  for (const bg of bgA) counts.set(bg, (counts.get(bg) || 0) + 1);
  let matches = 0;
  for (const bg of bgB) {
    const c = counts.get(bg) || 0;
    if (c > 0) { matches++; counts.set(bg, c - 1); }
  }
  return (2 * matches) / (bgA.length + bgB.length);
}

function fuzzyResolve(value, candidates) {
  const v = (value || '').toString().trim();
  if (!v) return { match: 'none', best: null, score: 0, candidates: [] };

  const exact = candidates.find(c => normaliseForMatch(c) === normaliseForMatch(v));
  if (exact) return { match: 'exact', best: exact, score: 1, candidates: [exact] };

  const scored = candidates
    .map(c => ({ c, score: diceCoefficient(v, c) }))
    .sort((a, b) => b.score - a.score);

  if (!scored.length || scored[0].score < 0.6) {
    return { match: 'none', best: null, score: scored[0] ? scored[0].score : 0, candidates: [] };
  }
  if (scored[0].score >= 0.85) {
    return { match: 'fuzzy', best: scored[0].c, score: scored[0].score, candidates: [scored[0].c] };
  }
  const top3 = scored.filter(s => s.score >= 0.6).slice(0, 3).map(s => s.c);
  return { match: 'ambiguous', best: scored[0].c, score: scored[0].score, candidates: top3 };
}

function isMissing(value, confidence) {
  if (value === null || value === undefined || value.toString().trim() === '') return true;
  const c = confidence != null ? Number(confidence) : 1;
  return c < LOW_CONF;
}

const confidence = entryIn.confidence || {};
const resolved = { project: null, activity: null };

function ruleProjectRequired() {
  if (isMissing(entryIn.project, confidence.project)) { missingFields.push('project'); return true; }
  return false;
}
function ruleActivityRequired() {
  if (isMissing(entryIn.activity, confidence.activity)) { missingFields.push('activity'); return true; }
  return false;
}
function ruleHoursRequired() {
  if (isMissing(entryIn.hours, confidence.hours)) { missingFields.push('hours'); return true; }
  return false;
}
function ruleTaskRequired() {
  if (isMissing(entryIn.task_description, 1)) { missingFields.push('task_description'); return true; }
  return false;
}

const projectMissing = ruleProjectRequired();
const allowedProjects = Array.isArray(assignment.projects) ? assignment.projects : [];
const allowedProjectNames = allowedProjects.map(p => p.project);

let projectEntry = null;

if (!projectMissing) {
  const projResult = fuzzyResolve(entryIn.project, allowedProjectNames);

  if (projResult.match === 'none') {
    errors.push({ code: 'PROJECT_NOT_FOUND', field: 'project', message: "I don't have a project by that name. Which of these was it?" });
  } else if (projResult.match === 'ambiguous') {
    errors.push({ code: 'AMBIGUOUS_MATCH', field: 'project', message: `Did you mean ${projResult.candidates.join(', ')}?` });
  } else {
    resolved.project = projResult.best;
    projectEntry = allowedProjects.find(p => p.project === projResult.best) || null;
  }
}

const activityMissing = ruleActivityRequired();

if (!activityMissing && projectEntry) {
  const activities = projectEntry.activities || [];
  const actResult = fuzzyResolve(entryIn.activity, activities);

  if (actResult.match === 'none') {
    errors.push({ code: 'ACTIVITY_NOT_IN_PROJECT', field: 'activity', message: `That activity isn't mapped to ${projectEntry.project}. Choose one of: ${activities.join(', ')}` });
  } else if (actResult.match === 'ambiguous') {
    errors.push({ code: 'AMBIGUOUS_MATCH', field: 'activity', message: `Did you mean ${actResult.candidates.join(', ')}?` });
  } else {
    resolved.activity = actResult.best;
  }
} else if (!activityMissing && !projectEntry) {
  const allActivities = Array.from(new Set(allowedProjects.flatMap(p => p.activities || [])));
  const actResult = fuzzyResolve(entryIn.activity, allActivities);
  if (actResult.match === 'exact' || actResult.match === 'fuzzy') {
    resolved.activity = actResult.best;
  } else if (actResult.match === 'ambiguous') {
    errors.push({ code: 'AMBIGUOUS_MATCH', field: 'activity', message: `Did you mean ${actResult.candidates.join(', ')}?` });
  } else if (actResult.match === 'none') {
    errors.push({ code: 'ACTIVITY_NOT_IN_PROJECT', field: 'activity', message: "I don't recognise that activity. Please pick from the menu." });
  }
}

let hoursValue = null;
const hoursMissing = ruleHoursRequired();

function ruleHoursValid() {
  const h = Number(entryIn.hours);
  if (!isFinite(h) || h <= 0) return false;
  const steps = h / HOURS_STEP;
  if (Math.abs(steps - Math.round(steps)) > 1e-6) return false;
  return true;
}

if (!hoursMissing) {
  if (!ruleHoursValid()) {
    errors.push({ code: 'HOURS_INVALID', field: 'hours', message: 'Please give a single number in quarter-hour steps, e.g. 6 or 6.5.' });
  } else {
    hoursValue = Math.round(Number(entryIn.hours) * 100) / 100;

    if (hoursValue > MAX_HOURS_PER_ENTRY) {
      errors.push({ code: 'HOURS_EXCEED_ENTRY_LIMIT', field: 'hours', message: `A single entry can be at most ${MAX_HOURS_PER_ENTRY} hours. Please give a smaller number.` });
    } else {
      const maxPerDay = employee.max_hours_per_day != null ? Number(employee.max_hours_per_day) : MAX_HOURS_PER_DAY_DEFAULT;
      const alreadyLogged = existingDayRows
        .filter(r => (r.Status || r.status || 'LOGGED') !== 'SUPERSEDED')
        .reduce((sum, r) => sum + (Number(r['Contributed Hours'] || r.hours) || 0), 0);

      if (alreadyLogged + hoursValue > maxPerDay) {
        const dateLabel = entryIn.work_date || todayLocal;
        errors.push({
          code: 'HOURS_EXCEED_DAILY_LIMIT',
          field: 'hours',
          message: `You've already logged ${alreadyLogged} h on ${dateLabel}. ${hoursValue} more would pass the ${maxPerDay} h daily limit.`
        });
      }
    }
  }
}

let workDate = (entryIn.work_date || '').toString().trim() || todayLocal;

function daysBetween(a, b) {
  const da = new Date(a + 'T00:00:00Z');
  const db = new Date(b + 'T00:00:00Z');
  return Math.round((db.getTime() - da.getTime()) / 86400000);
}

if (workDate && todayLocal) {
  const diff = daysBetween(todayLocal, workDate);
  if (diff > 0) {
    errors.push({ code: 'DATE_IN_FUTURE', field: 'work_date', message: "I can't log a future date." });
  } else if (-diff > BACKDATE_DAYS) {
    errors.push({ code: 'DATE_TOO_OLD', field: 'work_date', message: `That's more than ${BACKDATE_DAYS} days ago — please ask HR to add it.` });
  }
}

if (workDate && !errors.some(e => e.field === 'work_date')) {
  const d = new Date(workDate + 'T00:00:00Z');
  const isoWeekday = ((d.getUTCDay() + 6) % 7) + 1;
  if (!WORKING_DAYS.includes(isoWeekday)) {
    warnings.push({ code: 'WARN_WEEKEND', message: `Note: ${workDate} falls on a non-working day.` });
  }
}

const taskMissing = ruleTaskRequired();
let taskNormalised = null;

if (!taskMissing) {
  const raw = entryIn.task_description.toString().trim().replace(/\s+/g, ' ');
  taskNormalised = raw.length ? raw.charAt(0).toUpperCase() + raw.slice(1) : raw;

  if (taskNormalised.length < TASK_MIN_CHARS) {
    errors.push({ code: 'TASK_TOO_SHORT', field: 'task_description', message: 'Could you describe the work in a few more words?' });
  } else if (taskNormalised.length > TASK_MAX_CHARS) {
    errors.push({ code: 'TASK_TOO_LONG', field: 'task_description', message: `Task description is too long — please keep it under ${TASK_MAX_CHARS} characters.` });
  } else {
    const onlyDigits = /^\d+$/.test(taskNormalised.replace(/\s/g, ''));
    const equalsActivity = resolved.activity && normaliseForMatch(taskNormalised) === normaliseForMatch(resolved.activity);
    const lastTask = (input.last_session_task || '').toString().trim();
    const repeatsLast = lastTask && taskNormalised === lastTask;

    if (onlyDigits || equalsActivity || repeatsLast) {
      errors.push({ code: 'TASK_NOT_DESCRIPTIVE', field: 'task_description', message: 'Could you describe the work in a few more words?' });
    }
  }
}

let commentNormalised = (entryIn.additional_comments || '').toString().trim();
if (commentNormalised.length > COMMENT_MAX_CHARS) {
  errors.push({ code: 'COMMENT_TOO_LONG', field: 'additional_comments', message: `Comment is too long — please keep it under ${COMMENT_MAX_CHARS} characters.` });
}

if (resolved.project && resolved.activity && workDate) {
  const dup = existingDayRows.find(r => {
    const rProject = (r['Project Name'] || r.project || '').toString();
    const rActivity = (r['Activity Type'] || r.activity || '').toString();
    const rStatus = (r.Status || r.status || 'LOGGED').toString();
    return rStatus !== 'SUPERSEDED'
      && normaliseForMatch(rProject) === normaliseForMatch(resolved.project)
      && normaliseForMatch(rActivity) === normaliseForMatch(resolved.activity);
  });

  if (dup) {
    if (DUPLICATE_POLICY === 'BLOCK') {
      errors.push({ code: 'DUPLICATE_BLOCKED', field: null, message: `You've already logged ${dup['Contributed Hours'] || dup.hours} h of ${resolved.activity} on this date.` });
    } else {
      warnings.push({ code: 'WARN_POSSIBLE_DUPLICATE', message: `⚠️ You already logged ${dup['Contributed Hours'] || dup.hours} h of ${resolved.activity} on this date — is this separate work?` });
    }
  }
}

const normalisedEntry = {
  project: resolved.project,
  activity: resolved.activity,
  work_date: workDate,
  hours: hoursValue,
  task_description: taskNormalised,
  additional_comments: commentNormalised || null
};

const askOrder = ['project', 'activity', 'hours', 'task_description'];
const orderedMissing = askOrder.filter(f => missingFields.includes(f));

const ok = errors.length === 0 && orderedMissing.length === 0;

return [{
  json: {
    ok,
    entry: normalisedEntry,
    errors,
    warnings,
    missing_fields: orderedMissing,
    resolved
  }
}];
